// Transform a string to lower case
std::string to_lower(std::string str) {
    std::transform(str.begin(), str.end(), str.begin(), ::tolower);
    return(str);
}

std::string remove_chars(std::string str,
                         char remove_char) {
    str.erase(std::remove_if(str.begin(), str.end(), [remove_char](char c) {
        return c == remove_char;}), str.end());
    return(str);
}

std::string get_omop_identifier(std::string lab_id,
                                std::string lab_abbrv,
                                std::string lab_unit,
                                std::string sep) {

    // Currently identifying the OMOP concept by the lab ID and abbreviation.
    lab_id = concat_string(std::vector<std::string>({"\"", lab_id,  "\""}));
    lab_abbrv = concat_string(std::vector<std::string>({"\"", lab_abbrv,  "\""}));

    std::vector<std::string> omop_identifier_vec = {lab_id, lab_abbrv, lab_unit};
    std::string omop_identifier = concat_string(omop_identifier_vec, sep);

    return(omop_identifier);
} 

/** 
 * @brief Splits a string based on a given delimiter ignoring any delimiter inside "".
 * 
 * @param input string to split
 * @param delimiter delimiter to split on
 * 
 * @return vector of strings
 * 
 * @details
 * Splits a string based on a given delimiter. Assisted with basic coding tools. 
 * Splits string and ignored delimiter inside "". 
 */
std::vector<std::string> splitString(const std::string &input, 
                                     char delimiter) {
  std::vector<std::string> tokens;
  std::istringstream ss(input);
  std::string token;
  bool inQuotedString = false;

  for (char c : input) {
    if (c == '"') {
      inQuotedString = !inQuotedString; // Toggle quoted string state
    } else if ((c == delimiter && !inQuotedString)) {
      tokens.push_back(token);
      token.clear();
    } else {
      token += c;
    }
  }
  tokens.push_back(token); // Add the last token

  return tokens;
}

void add_quotation(std::string &str) {
    if(str != "NA") str = concat_string(std::vector<std::string>({"\"", str,  "\""}));
}

#include <vector>

#include "cascade-classifier.h"
#include "integral-image.h"
#include "strong-classifier.h"

/**
 * Constructor
 * @param {Int} baseResolution Base resolution for the cascade classifer
 */
CascadeClassifier::CascadeClassifier(int baseResolution) {
	this->baseResolution = baseResolution;
}

/**
 * Constructor
 * @param {Int}                           baseResolution Base resolution for the cascade classifier
 * @param {std::vector<StrongClassifier>} sc             A set of strong classifiers to add as layers
 */
CascadeClassifier::CascadeClassifier(int baseResolution, std::vector<StrongClassifier> sc) {
	this->baseResolution = baseResolution;
	this->strongClassifiers = sc;
}

/**
 * Destructively scale a cascade classifier relative to its base resolution
 * @param {Float} factor The factor by which to scale
 */
void CascadeClassifier::scale(float factor) {
	this->baseResolution *= factor;
	for (int i = 0; i < this->strongClassifiers.size(); i += 1) this->strongClassifiers[i].scale(factor);
}

/**
 * Add a strong classifier as a layer to a cascade classifier
 * @param {StrongClassifier} sc The strong classifier to add
 */
void CascadeClassifier::add(StrongClassifier sc) {
	this->strongClassifiers.push_back(sc);
}

/**
 * Remove the most recently added strong classifier associated with a cascade classifier
 */
void CascadeClassifier::removeLast() {
	this->strongClassifiers.pop_back();
}

/**
 * Classify a region of an integral image
 * @param  {IntegralImage} integral The integral image to classify
 * @param  {Int}           sx       Subwindow x offset
 * @param  {Int}           sy       Subwindow y offset
 * @param  {Float}         mean     The mean of the values within the subwindow (for post-normalization)
 * @param  {Float}         sd       The standard deviation of the values within the subwindow (for post normalization)
 * @return {Bool}                   True for positive detection, false for negative
 */
bool CascadeClassifier::classify(IntegralImage& integral, int sx, int sy, float mean, float sd) {
	for (int i = 0; i < this->strongClassifiers.size(); i += 1) {
		if (this->strongClassifiers[i].classify(integral, sx, sy, mean, sd) == false) return false;
	}
	return true;
}

/**
 * Get false positive rate for a cascade classifier
 * @param  {std::vector<IntegralImage>} negativeValidationSet A set of negative images to test
 * @return {Float}                                            Normalized false positive rate
 */
float CascadeClassifier::getFPR(std::vector<IntegralImage>& negativeValidationSet) {
	int falsePositives = 0;
	for (int i = 0; i < negativeValidationSet.size(); i += 1) {
		if (this->classify(negativeValidationSet[i], 0, 0, 0, 1) == true) falsePositives += 1;
	}
	return (float)falsePositives / negativeValidationSet.size();
}

/**
 * Get false negative rate for a cascade classifier
 * @param  {std::vector<IntegralImage>} positiveValidationSet A set of positive images to test
 * @return {Float}                                            Normalized false negative rate
 */
float CascadeClassifier::getFNR(std::vector<IntegralImage>& positiveValidationSet) {
	int falseNegatives = 0;
	for (int i = 0; i < positiveValidationSet.size(); i += 1) {
		if (this->classify(positiveValidationSet[i], 0, 0, 0, 1) == false) falseNegatives += 1;
	}
	return (float)falseNegatives / positiveValidationSet.size();
}

#include "includes/AssetManager.hpp"

namespace RT {

// =================== ASSET MANAGER ==============================

std::optional<fs::path> AssetManager::set(uuid id, fs::path path,
                                          bool no_copy) {
  // 1) check if path is valid and points to a file by accessing it
  if (!can_open_file(path)) {
    LOG_ERROR(std::format("cannot open path \"{}\"", path.string()));
    return {};
  }

  // 2) check if the given uuid is already present
  //    this isn't neccessarily an error, but it can lead to inconsistent
  //    behaviour
  auto opath = get(id);
  if (opath.has_value()) {
    LOG_WARN(std::format("ID \"{}\" already exists!! This can result in "
                         "inconsistent behaviour!!",
                         boost::uuids::to_string(id)));
  }

  // 3) if the given path is not in the asset folder, make a copy
  if (!no_copy) {
    auto new_path = copy_file_and_replace_path(path);
    if (!new_path.has_value()) {
      return {};
    }
    path = fs::relative(new_path.value(), fs::canonical(fs::current_path()));
  }

  LOG(std::format("adding a new path \"{}\" with UUID \"{}\"", path.string(),
                  boost::uuids::to_string(id)));
  _um->add(id, this);
  _storage[id] = path;
  return {path};
}

std::optional<std::pair<AssetManager::uuid, fs::path>>
AssetManager::create(fs::path path, bool no_copy) {
  // 1) check if path is valid and points to a file by accessing it
  if (!can_open_file(path)) {
    LOG_ERROR(
        std::format("Cannot open path \"{}\". Wrong path?", path.string()));
    return {};
  }

  if (!no_copy) {
    auto new_path = copy_file_and_replace_path(path);
    if (!new_path.has_value()) {
      return {};
    }
    path = fs::relative(new_path.value(), fs::canonical(fs::current_path()));
  }

  auto id = _um->create(this);
  LOG(std::format("added new path \"{}\" with UUID \"{}\"", path.string(),
                  boost::uuids::to_string(id)));
  _storage[id] = path;
  return std::make_optional<std::pair<uuid, fs::path>>(
      std::make_pair(id, path));
}

void AssetManager::print() {
  VariadicTable<std::string, std::string> vt({"UUID", "Path"});

  for (const auto &[id, path] : _storage) {
    vt.addRow(boost::uuids::to_string(id), path.string());
  }

  // TODO: Use Log class as an option? -> Print tables to file
  vt.print(std::cout);
  std::cout << std::endl;
}

// Assisted with basic coding tools with slight modifications
bool AssetManager::can_open_file(const fs::path &path) {
  auto p = fs::absolute(path).string();
  std::ifstream file(fs::absolute(path)); // Try to open the file in read mode
  if (file.is_open()) {
    file.close(); // Close the file if it was successfully opened
    return true;
  }
  LOG_ERROR(std::format("ERROR PATH: {}", path.string()));
  return false;
}

// Assisted with basic coding tools with slight modifications
bool AssetManager::is_path_in_subfolder(const fs::path &targetPath) {
  try {
    // Get the path of the executable
    auto exeDir = fs::canonical(fs::current_path());
    LOG(std::format("exeDIR: {}", exeDir.string()));

    // Get the canonical (absolute) path of the target
    auto resolvedTargetPath = fs::canonical(targetPath);
    LOG(std::format("targetPath: {}", resolvedTargetPath.string()));

    // Check if the target path starts with the executable directory
    return resolvedTargetPath.string().find(exeDir.string()) == 0 &&
           resolvedTargetPath != exeDir;
  } catch (const fs::filesystem_error &e) {
    std::cerr << "Error: " << e.what() << std::endl;
    return false;
  }
}

// Assisted with basic coding tools with slight modifications
std::optional<fs::path>
AssetManager::copy_file_to_subfolder(const fs::path &targetPath) {
  try {
    // Get executable's directory
    auto exePath = fs::current_path();
    auto exeDir = fs::canonical(exePath);

    // Resolve absolute path of the target file
    auto resolvedTargetPath = fs::canonical(targetPath);

    // Generate relative path from the target's filename
    auto fileName = resolvedTargetPath.filename();
    auto destinationPath = get_relative_asset_folder_path() / fileName;

    // Ensure the destination directory exists
    fs::create_directories(destinationPath.parent_path());

    // Copy the file to the new location
    fs::copy_file(resolvedTargetPath, destinationPath,
                  fs::copy_options::overwrite_existing);

    // Calculate and return the relative path of the copied file
    return fs::relative(resolvedTargetPath, exeDir).string();
  } catch (const fs::filesystem_error &e) {
    std::cerr << "File copy failed: " << e.what() << std::endl;
    return {};
  }
}

std::optional<fs::path>
AssetManager::copy_file_and_replace_path(const fs::path &srcPath) {
  if (!is_path_in_subfolder(srcPath)) {
    auto dest_path = copy_file_to_subfolder(srcPath);
    if (!dest_path.has_value()) {
      LOG_ERROR(std::format("Error during copy!", srcPath.string()));
      return {};
    }
    if (!can_open_file(dest_path.value())) {
      LOG_ERROR(std::format("Cannot open path \"{}\". Error during copy?",
                            srcPath.string()));
      return {};
    }
    return dest_path;
  }
  return std::make_optional<fs::path>(srcPath);
}

// =================== ASSET =====================================

void AssetManager::Asset::set(uuid id, fs::path path, bool no_copy) {
  LOG(std::format("Try adding Asset \"{}\" ({})", path.string(),
                  boost::uuids::to_string(id)));
  _am->set(id, path, no_copy);
}
bool AssetManager::Asset::set_uuid(uuid id) {
  // check if uuid is known on manager
  // -> if not in manager, this uuid is invalid
  // => this is used when reading from a json (where the all assets are loaded
  //    before use in the scene)
  auto opath = _am->get(id);
  if (!opath.has_value()) {
    LOG_ERROR(std::format("UUID ({}) doesn't exist yet",
                          boost::uuids::to_string(id)));
    return false;
  }
  _uuid = id;
  _path = opath.value();
  LOG(std::format("Asset \"{}\" ({}) exists", _path.string(),
                  boost::uuids::to_string(_uuid)));
  return true;
}
bool AssetManager::Asset::set_path(fs::path path, bool no_copy) {
  // 1) check if path is already in the asset manager
  auto existing_uuid = _am->get(path);
  if (existing_uuid.has_value()) {
    _uuid = existing_uuid.value();
    _path = path;
    LOG(std::format("Asset \"{}\" ({}) exists", path.string(),
                    boost::uuids::to_string(_uuid)));
    return true;
  }

  // 2) otherwise create a new entry in asset manager
  auto pair = _am->create(path, no_copy);
  if (!pair.has_value()) {
    LOG_ERROR(std::format("Error during Asset creation... \"{}\"", path.string()));
    return false;
  }

  _uuid = pair.value().first;
  _path = pair.value().second;
  return true;
}

