MouseEye::MouseEye(int sck, int sdio)
{
	//	SET PIN DIRECTION
  pinMode(sck, OUTPUT);
  pinMode(sdio, INPUT);
  digitalWrite(sck,HIGH);	//clock idles high
  // initialize pin states and prepare default config settings
  _SCK = sck;	// keep track of the clock pin
  _SDIO = sdio;	// keep track of the data  pin

}

//////////////////////////////////////////
//	PUBLIC FUNCTIONS
//////////////////////////////////////////

void MouseEye::getMouseEyeDelta()
{
deltaY = readDNS(0x42);
deltaX = readDNS(0x43);
deltaY = ~deltaY; deltaY++;	// invert deltaY
}


byte MouseEye::Config_R()
{
byte n = readDNS(0x40);
return n;
}

void MouseEye::Config_W(byte cfig)
{
writeDNS(0x40,cfig);
}

byte MouseEye::Status()
{
byte n = readDNS(0x41);
return n;
}

byte MouseEye::Squal()
{
b = readDNS(0x44);
return b;
}

byte MouseEye::Max_P()
{
b = readDNS(0x45);
return b;
}

byte MouseEye::Min_P()
{
b = readDNS(0x46);
return b;
}

byte MouseEye::Pixel_Sum()
{
b = readDNS(0x47);
b *= 0.395;
return b;
}

word MouseEye::Shutter()
{
word w;
sUpper = readDNS(0x49);
sLower = readDNS(0x4A);
w = sUpper << 8;
w += sLower;
return w;
}

