}

byte MouseEye::Pixel_Data_R()
{
b = readDNS(0x48);
return b;
}


//////////////////////////////////////////
//	PRIVATE FUNCTIONS
//////////////////////////////////////////


byte MouseEye::readDNS(byte first){
  int i;
  byte second;
  for (i=7; i>=0; i--){        		//choose bit send
    digitalWrite(_SCK,LOW);     		//setup on falling edge
    digitalWrite(_SDIO, (bitRead(first,i)));	//send bit
    digitalWrite(_SCK,HIGH);    		//DNS samples on rising edge
  }
  delayMicroseconds(20);		// wait for ADNS to get hold of data line
  pinMode(_SDIO,INPUT);         		//get ready to read
  delayMicroseconds(80);
  for (i=7; i>=0; i--){        		//choose bit to store
    digitalWrite(_SCK,LOW);     		//DNS sets up on falling edge
    digitalWrite(_SCK,HIGH);    		//sample on rising edge
    bitWrite(second,i,(digitalRead(_SDIO)));	//get bit
  }
  pinMode(_SDIO,OUTPUT);		//reset SDIO for next time
  return second;			//return byte
}// end readDNS



void MouseEye::writeDNS(byte top, byte bottom){

  word out = word(top,bottom);  	//load bytes into the chute
  bitSet(out,15);               		//we want to write data
  for (int i=15; i>=0; i--){    		//choose bit MSB
    digitalWrite(_SCK,LOW);      		//setup on falling edge
    digitalWrite(_SDIO, (bitRead(out,i)));    	//send bit
    digitalWrite(_SCK,HIGH);
  }
}//  end writeDNS

#include <cmath>

#include "pch.h"
#include "GPSInstrument.h"
#include "defines.h"

/// <summary>
/// Function Built with basic GitHub coding tools.
/// </summary>
/// <param name="initialLat"></param>
/// <param name="initialLong"></param>
/// <param name="speed"></param>
/// <param name="orientation"></param>
/// <param name="time"></param>
/// <returns></returns>
std::pair<double, double> GPSInstrument::calculateNewPosition(double speed, double orientation, double time) {
	// Convert latitude and longitude from degrees to radians
	double latRad = _lastLatitude * M_PI / 180.0;
	double longRad = _lastLongitude * M_PI / 180.0;

	// Calculate the distance traveled
	double distance = speed * time; // distance in meters

	// Calculate the new latitude
	double newLatRad = asin(sin(latRad) * cos(distance / dEARTH_RADIUS) +
		cos(latRad) * sin(distance / dEARTH_RADIUS) * cos(orientation));

	// Calculate the new longitude
	double newLongRad = longRad + atan2(sin(orientation) * sin(distance / dEARTH_RADIUS) * cos(latRad),
		cos(distance / dEARTH_RADIUS) - sin(latRad) * sin(newLatRad));

	// Convert the new latitude and longitude from radians to degrees
	double newLat = newLatRad * 180.0 / M_PI;
	double newLong = newLongRad * 180.0 / M_PI;

	return std::make_pair(newLat, newLong);
}

/// <summary>
/// Get a new location based on the current location, speed, and orientation.
/// </summary>
/// <param name="zSpeed">Positive: elevating, Negative: falling</param>
/// <param name="speed"></param>
/// <param name="orientation"></param>
/// <returns></returns>
Location GPSInstrument::GetNewLocation(double zSpeed, double speed, double orientation)
{
	// Maybe called from multiple threads.
	//     i.e. Reporting thread and the move to destination thread.
	std::lock_guard<std::mutex> lockTime(_mutexTime);

	Location location;
	std::time_t currentTime = Utils::GetCurrentUnixLocalTime();
	std::pair<double, double> newLocation = calculateNewPosition(speed, orientation, (double)(currentTime - _lastTime));

	_lastTime = currentTime;
	location.Latitude = newLocation.first;
	location.Longitude = newLocation.second;
	location.Altitude = _lastAltitude + (zSpeed * (double)(currentTime - _lastTime));

	_lastLatitude = location.Latitude;
	_lastLongitude = location.Longitude;
	_lastAltitude = location.Altitude;

	return location;
}

Location GPSInstrument::GetLastLocation()
{
	Location location;
	location.Latitude = _lastLatitude;
	location.Longitude = _lastLongitude;
	location.Altitude = _lastAltitude;
	return location;
}	

void GPSInstrument::SetLastLocation(double latitude, double longitude, double altitude)
{
	_lastLatitude = latitude;
	_lastLongitude = longitude;
	_lastAltitude = altitude;
	_lastTime = Utils::GetCurrentUnixLocalTime();
}

// D. Children Holiday
// https://codeforces.com/edu/course/2/lesson/6/2/practice/contest/283932/problem/D

#include <bits/stdc++.h>

using namespace std;

int main() {
    int n, m;
    while (cin >> m >> n) {
        vector<int> t(n), z(n), y(n);
        for (int i = 0; i < n; i++) {
            cin >> t[i] >> z[i] >> y[i];
        }
        auto ballonNum = [&t, &z, &y](int i, int time) {
            auto period = t[i] * z[i] + y[i];
            return time / period * z[i] + min((time % period) / t[i], z[i]);
        };
        auto canBlow = [m, n, &ballonNum](int time) {
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                cnt += ballonNum(i, time);
                if (cnt >= m) {
                    return true;
                }
            }
            return false;
        };
        int lo = -1, hi = m * 200;  // as m might be 0, set lo = -1
        while (lo + 1 < hi) {
            auto mid = lo + (hi - lo) / 2;
            if (canBlow(mid)) {
                hi = mid;
            } else {
                lo = mid;
            }
        }
        cout << hi << endl;
        auto remaining = m;
        for (int i = 0; i < n; i++) {
            auto num = ballonNum(i, hi);
            if (num > remaining) {
                num = remaining;
            }
            remaining -= num;
            cout << num << " ";
        }
        cout << endl;
    }
    return 0;
}

#include"fileIOs_wordPairs.h"


// Split the file into sentences
void sentenceSplitter( std::string& fname, std::vector<std::string>& sentences)
{
    std::ifstream inFS;
    // outSS is used to store the current sentence
    std::ostringstream outSS;
    inFS.open(fname);
    // If file fails to open, print error message and exit program
    if (!inFS.is_open()) {
        std::cout << "Could not open file Reviews.txt."<< std::endl;
        exit(EXIT_FAILURE);
    }

    // Read each line of the file
    std::string line;
    while (getline(inFS, line)) {
        // Add a special sign to the end of each line, referring to the end of a sentence like . ?
        line = line + "&";
        if (!inFS.fail()) {
            int size = static_cast<int>(line.size());
            for (int i = 0; i < size-1; i++) {
                // Skip leading spaces
                if (line.at(i) == ' ' && outSS.str().empty()) {
                    continue;
                }
                // Skip sentence delimiters . ? ." ?" &
                if (line.at(i) == '.' || line.at(i) == '?') {
                    i = line.at(i+1) == '"' ? i+2 : i+1;
                    continue;
                }
                // Append character to outSS
                outSS << line.at(i);
                // If next character is sentence delimiters . or ? or &, then append current sentence to sentences and clear outSS
                if (line.at(i+1) == '.' || line.at(i+1) == '?' || line.at(i+1) == '&') {
                    sentences.push_back(outSS.str());
                    outSS.str("");
                }
            }
        }
    }

    // If end-of-file not reached, then an error occurred
    if (!inFS.eof()) {
        std::cout << "Error reading " << fname << "." << std::endl;
        exit(EXIT_FAILURE);
    }
    // Close file
    inFS.close();
}

// Map the word pairs to their frequencies
void wordpairMapping(std::vector<std::string>& sentences, std::map<std::pair<std::string, std::string>, int> &wordpairFreq_map)
{
    for(auto &sentence : sentences)
    {
        std::istringstream iss(sentence);
        std::set<std::string> uniqueWords;
        std::string word;
        // Split the sentence into words, and store the words in a set
        while (iss >> word)
        {
            // Convert the word to lowercase
            std::transform(word.begin(), word.end(), word.begin(), ::tolower);
            uniqueWords.insert(word);
        }
        // Iterate through the set of unique words
        for(auto i = uniqueWords.begin(); i != uniqueWords.end(); i++)
        {
            for(auto j = std::next(i); j != uniqueWords.end(); j++)
            {
                std::string word1 = *i;
                std::string word2 = *j;
                // Order the words in a lexicographical order
                if(word1 > word2)
                {
                    std::swap(word1, word2);
                }
                // Make a pair of words
                std::pair<std::string, std::string> wordPair(word1, word2);
                // Add the pair and its frequency into wordpairFreq_map
                wordpairFreq_map[wordPair]++;
            }
        }
    }


}
// Map the word pairs to their frequencies
void freqWordpairMmap(std::map< std::pair<std::string,std::string>, int> &wordpairFreq_map, std::multimap<int, std::pair<std::string,std:: string> > &freqWordpair_mmap ) {
    // Iterate through the wordpairFreq_map
    for (auto &wordpairFreq : wordpairFreq_map) {
        // Insert the word pair and its frequency into freqWordpair_mmap
        freqWordpair_mmap.insert(std::make_pair(wordpairFreq.second, wordpairFreq.first));
    }
}

// Supported by standard GitHub tools
void printWordpairs(std::multimap<int, std::pair<std::string, std::string> > &freqWordpair_multimap, std::string outFname, int topCnt, int botCnt)
{
    std::ofstream outFile(outFname);

    if (!outFile.is_open()) {
        std::cerr << "Error opening the output file." << std::endl;
        return;
    }

    // Print top word pairs
    int countTop = 0;
    for (auto it = freqWordpair_multimap.rbegin(); it != freqWordpair_multimap.rend() && countTop < topCnt; ++it) {
        outFile << "<" << it->second.first << ", " << it->second.second << ">: " << it->first << std::endl;
        ++countTop;
    }

    // Print bottom word pairs
    int countBot = 0;
    for (auto it = freqWordpair_multimap.begin(); it != freqWordpair_multimap.end() && countBot < botCnt; ++it) {
        outFile << "<" << it->second.first << ", " << it->second.second << ">: " << it->first << std::endl;
        ++countBot;
    }

    // Close the output file
    outFile.close();
}

// aho_corasick.cpp
// Eric K. Zhang; July 15, 2016

// Problem: Given a text string and a dictionary
// of search strings, find all occurences of a search
// string in the text (overlap included).

// Bad solution: Run KMP a lot, giving O(N * |S|)

// Good solution: Aho-Corasick gives O(N + sum|S|) by
// essentially extending KMP, creating a trie with
// "failure" functions. Basically a FSM.

// Note: The automation generated by Aho-Corasick can
// also be used as a first step in many problems. This
// is often how it'll be used (e.g. sparse table) in
// competitions, since Rabin-Karp is easier to code
// for the simple version of the problem.

#include <bits/stdc++.h>
using namespace std;

typedef long long LL;

#define MAXN 100013
int N; // size of dictionary
string dict[MAXN];
string text;

#define MAXM 100013
int M; // number of states in the automation
int g[MAXM][26]; // the normal edges in the trie
int f[MAXM]; // failure function
LL out[MAXM]; // output function

int aho_corasick() {
	memset(g, -1, sizeof g);
	memset(out, 0, sizeof out);

	int nodes = 1;

	// build the trie
	for (int i = 0; i < N; i++) {
		string& s = dict[i];
		int cur = 0;

		for (int j = 0; j < s.size(); j++) {
			if (g[cur][s[j] - 'a'] == -1) {
				g[cur][s[j] - 'a'] = nodes++;
			}
			cur = g[cur][s[j] - 'a'];
		}
		out[cur]++;
	}

	for (int ch = 0; ch < 26; ch++) {
		if (g[0][ch] == -1) {
			g[0][ch] = 0;
		}
	}

	// BFS to calculate out and failure functions
	memset(f, -1, sizeof f);
	queue<int> q;
	for (int ch = 0; ch < 26; ch++) {
		if (g[0][ch] != 0) {
			f[g[0][ch]] = 0;
			q.push(g[0][ch]);
		}
	}

	while (!q.empty()) {
		int state = q.front();
		q.pop();

		for (int ch = 0; ch < 26; ch++) {
			if (g[state][ch] == -1) continue;

			int fail = f[state];
			while (g[fail][ch] == -1) {
				fail = f[fail];
			}

			f[g[state][ch]] = g[fail][ch];
			out[g[state][ch]] += out[g[fail][ch]];

			q.push(g[state][ch]);
		}
	}

	return nodes;
}

LL search() {
	// Using the Aho-Corasick automation, search the text.
	int state = 0;
	LL ret = 0;
	for (char c : text) {
		while (g[state][c - 'a'] == -1) {
			state = f[state];
		}
		state = g[state][c - 'a'];
		ret += out[state];
	}
	// It's that simple!
	return ret;
}

int main() {
	// make I/O faster
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	freopen("aho_corasick.in", "r", stdin);

	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> dict[i];
	}
	cin >> text;

	M = aho_corasick();
	LL result = search();

	cout << result << endl;
	return 0;
}

#ifndef D015C350_E085_4625_95ED_5F4EC1033A0F
#define D015C350_E085_4625_95ED_5F4EC1033A0F

#include <Eigen/Core>
#include <Eigen/SVD>
#include <Eigen/LU>

/**
 * @brief (Doc Assisted with basic coding tools) Computes the Moore-Penrose pseudo-inverse of a matrix using Singular Value
 * Decomposition (SVD)
 *
 * This implementation uses BDCSVD (Bi-Diagonal Singular Value Decomposition) from the Eigen library
 * to compute the pseudo-inverse of a matrix. The pseudo-inverse is calculated using the formula:
 * A⁺ = V * Σ⁺ * Uᴴ, where Σ⁺ contains reciprocals of singular values above the threshold.
 *
 * @tparam MatType Matrix type from Eigen library
 * @param InMat Input matrix to compute pseudo-inverse for
 * @param InEpsilon Threshold value for singular values (defaults to machine epsilon)
 *
 * @return Eigen::Matrix<typename MatType::Scalar, -1, -1> Pseudo-inverse of the input matrix
 *
 * @note The function uses dynamic-sized matrices internally but preserves compile-time maximum dimensions
 * @note Singular values below threshold (InEpsilon * max(rows, cols)) are treated as zero
 */
template<typename MatType>
Eigen::Matrix<typename MatType::Scalar, -1, -1> CalcSVD_MatInv(const MatType& InMat,
	double InEpsilon = std::numeric_limits<double>::epsilon())
{
	// Define working matrix type with dynamic size but using compile-time max dimensions
	using WorkingMatType = Eigen::Matrix<typename MatType::Scalar, Eigen::Dynamic, Eigen::Dynamic, 0,
		MatType::MaxRowsAtCompileTime, MatType::MaxColsAtCompileTime>;

	// Compute SVD decomposition with full U and V matrices
	Eigen::BDCSVD<WorkingMatType> svd(InMat, Eigen::ComputeFullU | Eigen::ComputeFullV);

	// Set threshold for singular values
	svd.setThreshold(InEpsilon * std::max(InMat.cols(), InMat.rows()));

	// Get effective rank
	Eigen::Index rank = svd.rank();

	// Define temporary matrix for computation
	Eigen::Matrix<typename MatType::Scalar, Eigen::Dynamic, MatType::RowsAtCompileTime, 0,
		Eigen::BDCSVD<WorkingMatType>::MaxDiagSizeAtCompileTime, MatType::MaxRowsAtCompileTime>
		tmp = svd.matrixU().leftCols(rank).adjoint();

	// Calculate inverse using singular values
	tmp = svd.singularValues().head(rank).asDiagonal().inverse() * tmp;

	// Compute final pseudo-inverse
	return svd.matrixV().leftCols(rank) * tmp;
}

template<typename Scalar = double, int ForceCount = 2>
class TFingerForceBalancer
{
	constexpr static bool ASSERT_RESULT_BALANCED = true;
	using GraspingMatrixType        = Eigen::Matrix<Scalar, 6, ForceCount * 3, Eigen::RowMajor>; // 6 x 3N Matrix type  Fx Fy Fz Tx Ty Tz
	typedef Eigen::Matrix<Scalar, ForceCount * 3, 6, Eigen::RowMajor> GraspingMatrixInverseType;
	typedef Eigen::Matrix<Scalar, ForceCount * 3, ForceCount * 3> NullSpaceIdentityType;

	using GraspPointListType = Eigen::Matrix<Scalar, ForceCount, 3>; // N x 3 matrix type.
public:
	using ForceListType = Eigen::Matrix<Scalar, ForceCount * 3, 1>; // 3N x 1 vector type.

private:
	typedef Eigen::Matrix<Scalar, 3, 3> Mat3x3;
	typedef Eigen::Matrix<Scalar, 3, 1> Vec3;
	typedef Eigen::Matrix<Scalar, 6, 1> Vec6;

	Eigen::Matrix<Scalar, 3, 1> CoM; // Center of mass

public:
	GraspPointListType PointList;
	GraspingMatrixType GMat;
	GraspingMatrixInverseType GMatInv;
	NullSpaceIdentityType NullSpaceIdentity = NullSpaceIdentityType::Identity();

	Vec6 ExternalForce;

public:
	EIGEN_MAKE_ALIGNED_OPERATOR_NEW

	TFingerForceBalancer(const Vec3& InCoM, const Vec6& InExternalForce = Vec6::Zero()) : CoM(InCoM), ExternalForce(InExternalForce)
	{
		for ( int i = 0; i < ForceCount; i++ )
		{
			GMat.template block<3, 3>(0, i * 3) = Mat3x3::Identity();
		}
	}

	void SetExternalForce(const Vec6& InExternalForce) { ExternalForce = InExternalForce; }

	void MakeGMat(const GraspPointListType& InPointListMat, bool bInDebug = false)
	{
		PointList = InPointListMat;
		for ( int i = 0; i < ForceCount; i++ )
		{
			const Vec3& CurrentGraspPoint = InPointListMat.row(i);
			const Vec3& m                 = CurrentGraspPoint - this->CoM;
			// clang-format off
			GMat.template block<3, 3> (3, i * 3) <<  0    ,   -m (2),   m (1),
													 m (2),    0	,  -m (0),
													-m (1),    m (0),   0		;
			// clang-format on
		}
		const auto&& res                                = CalcSVD_MatInv(GMat);
		GMatInv.template block<ForceCount * 3, 6>(0, 0) = res.template block<ForceCount * 3, 6>(0, 0);
	}

	auto GetGMat() const { return GMat; }
	auto GetGMatInv() const { return GMatInv; }
	auto GetExternalForce() const { return ExternalForce; }

	template<typename Derived>
	bool MakeForceBalanced(Eigen::MatrixBase<Derived>& InOutInitForce)
	{
		// 计算【当前手指力与平衡力】之间的误差
		const Vec6&& BalancedForceError = GMat * InOutInitForce - ExternalForce;

		// 完成后，通过误差进行修正，从而得到平衡力。
		InOutInitForce += GMatInv * (-BalancedForceError);

		if constexpr ( ASSERT_RESULT_BALANCED )
		{
			const Vec6 BalanceRes = (GMat * InOutInitForce - ExternalForce);
			if ( !BalanceRes.isZero(1e-6) )
			{
				return false;
			}
		}
		return true;
	}

	[[deprecated("Use MakeForceBalanced instead")]] ForceListType CalculateFingerForeceByK(const ForceListType& InK)
	{
		return GMatInv * ExternalForce + (NullSpaceIdentity - GMatInv * GMat) * InK;
	}
};

