#include <ros/ros.h>
#include <sensor_msgs/PointCloud2.h>
#include <pcl_conversions/pcl_conversions.h>
#include <pcl/point_cloud.h>
#include <pcl/point_types.h>
#include <pcl/filters/passthrough.h>
#include <pcl/segmentation/extract_clusters.h>
#include <pcl_ros/point_cloud.h>
#include <pcl/common/centroid.h>

class PointCloudObjectIdentifier
{
public:
    PointCloudObjectIdentifier()
    {
        // Subscribe to the input point cloud topic
        sub_ = nh_.subscribe("/pcl_cluster_input", 1, &PointCloudObjectIdentifier::pointCloudCallback, this);
        // Advertise the output point cloud topic for clusters
        clusters_pub_ = nh_.advertise<sensor_msgs::PointCloud2>("/pcl_cluster_output", 1);
        // Advertise the output point cloud topic for clusters
        centroids_pub_ = nh_.advertise<sensor_msgs::PointCloud2>("/pcl_centroid_output", 1);
        nh_.param<double>("/cluster_tolerance", cluster_tolerance_, 0.10);
        nh_.param<double>("/min_cluster_size", min_cluster_size_, 5);
        nh_.param<double>("/max_cluster_size", max_cluster_size_, 5000);

        // ROS_INFO("Cluster Proximity Tolerance: %f", cluster_tolerance_);
    }

    void pointCloudCallback(const sensor_msgs::PointCloud2ConstPtr& input)
    {
        pcl::PointCloud<pcl::PointXYZ>::Ptr cloud(new pcl::PointCloud<pcl::PointXYZ>);
        pcl::fromROSMsg(*input, *cloud);

        // Perform Euclidean Cluster Extraction
        pcl::search::KdTree<pcl::PointXYZ>::Ptr tree(new pcl::search::KdTree<pcl::PointXYZ>);
        tree->setInputCloud(cloud);

        std::vector<pcl::PointIndices> cluster_indices;
        pcl::EuclideanClusterExtraction<pcl::PointXYZ> ec;
        ec.setClusterTolerance(cluster_tolerance_);
        ec.setMinClusterSize(min_cluster_size_);
        ec.setMaxClusterSize(max_cluster_size_);
        ec.setSearchMethod(tree);
        ec.setInputCloud(cloud);
        ec.extract(cluster_indices);

        // Create a new PointCloud for the clusters
        pcl::PointCloud<pcl::PointXYZ>::Ptr clusters(new pcl::PointCloud<pcl::PointXYZ>);

        for (const auto& indices : cluster_indices)
        {
            for (const auto& index : indices.indices)
            {
                clusters->points.push_back(cloud->points[index]);
            }
        }

        // Convert the PCL PointCloud to ROS PointCloud2 and publish
        sensor_msgs::PointCloud2 output;
        pcl::toROSMsg(*clusters, output);
        output.header = input->header;
        clusters_pub_.publish(output);

        // Create a new PointCloud for the cluster centroids
        pcl::PointCloud<pcl::PointXYZ>::Ptr centroids(new pcl::PointCloud<pcl::PointXYZ>);

        for (const auto& indices : cluster_indices)
        {
            Eigen::Vector4f centroid;
            pcl::compute3DCentroid(*cloud, indices, centroid);
            pcl::PointXYZ centroid_point(centroid[0], centroid[1], centroid[2]);
            centroids->points.push_back(centroid_point);
        }

        // Convert the PCL PointCloud to ROS PointCloud2 and publish
        sensor_msgs::PointCloud2 centroids_output;
        pcl::toROSMsg(*centroids, centroids_output);
        centroids_output.header = input->header;
        centroids_pub_.publish(centroids_output);
    }

private:
    ros::NodeHandle nh_;
    ros::Subscriber sub_;
    ros::Publisher clusters_pub_;
    ros::Publisher centroids_pub_;

    double cluster_tolerance_;
    double min_cluster_size_;
    double max_cluster_size_;
};

int main(int argc, char** argv)
{
    ros::init(argc, argv, "point_cloud_object_identifier");
    PointCloudObjectIdentifier node;
    ros::spin();
    return 0;
}

#include <CL/cl.hpp>
#include <fstream>
#include <iostream>
#include <vector>
#include <time.h>

// =================================================================
// ---------------------- Secondary Functions ----------------------
// =================================================================

cl::Device getDefaultDevice();                          // Return the first device found in this OpenCL platform.
void initializeDevice();                                // Inicialize device and compile kernel code.
void seqSumArrays(int* a, int* b, int* c, const int N); // Sequentially performs the N-dimensional operation c = a + b.
void parSumArrays(int* a, int* b, int* c, const int N); // Parallelly performs the N-dimensional operation c = a + b.
bool checkEquality(int* c1, int* c2, const int N);      // Check if the N-dimensional arrays c1 and c2 are equal.

// =================================================================
// ------------------------ Global Variables ------------------------
// =================================================================

cl::Program program;    // The program that will run on the device.    
cl::Context context;    // The context which holds the device.    
cl::Device device;      // The device where the kernel will run.

// =================================================================
// ------------------------- Main Function -------------------------
// =================================================================

int main(){

    /**
     * Create auxiliary variables.
     * */

    clock_t start, end;
    const int EXECUTIONS = 10;

    /**
     * Prepare input arrays.
     * */

    int ARRAYS_DIM = 1 << 20;
    std::vector<int> a(ARRAYS_DIM, 3);
    std::vector<int> b(ARRAYS_DIM, 5);

    /**
     * Prepare sequential and parallel outputs.
     * */

    std::vector<int> cs(ARRAYS_DIM);
    std::vector<int> cp(ARRAYS_DIM);

    /**
     * Sequentially sum arrays.
     * */

    start = clock();
    for(int i = 0; i < EXECUTIONS; i++){
        seqSumArrays(a.data(), b.data(), cs.data(), ARRAYS_DIM);
    }
    end = clock();
    double seqTime = ((double) 10e3 * (end - start)) / CLOCKS_PER_SEC / EXECUTIONS;

    /**
     * Initialize OpenCL device.
     * */

    initializeDevice();

    /**
     * Parallelly sum arrays.
     * */

    start = clock();
    for(int i = 0; i < EXECUTIONS; i++){
        parSumArrays(a.data(), b.data(), cp.data(), ARRAYS_DIM);
    }
    end = clock();
    double parTime = ((double) 10e3 * (end - start)) / CLOCKS_PER_SEC / EXECUTIONS;

    /**
     * Check if outputs are equal.
     * */

    bool equal = checkEquality(cs.data(), cp.data(), ARRAYS_DIM);

    /**
     * Print results.
     * */

    std::cout << "Status: " << (equal ? "SUCCESS!" : "FAILED!") << std::endl;
    std::cout << "Results: \n\ta[0] = " << a[0] << "\n\tb[0] = " << b[0] << "\n\tc[0] = a[0] + b[0] = " << cp[0] << std::endl;
    std::cout << "Mean execution time: \n\tSequential: " << seqTime << " ms;\n\tParallel: " << parTime << " ms." << std::endl;
    std::cout << "Performance gain: " << (100 * (seqTime - parTime) / parTime) << "\%\n";
    return 0;
}

// =================================================================
// ---------------------- Secondary Functions ----------------------
// =================================================================

/**
 * Return the first device found in this OpenCL platform.
 * */

cl::Device getDefaultDevice(){

    /**
     * Search for all the OpenCL platforms available and check
     * if there are any.
     * */

    std::vector<cl::Platform> platforms;
    cl::Platform::get(&platforms);

    if (platforms.empty()){
        std::cerr << "No platforms found!" << std::endl;
        exit(1);
    }

    /**
     * Search for all the devices on the first platform and check if
     * there are any available.
     * */

    auto platform = platforms.front();
    std::vector<cl::Device> devices;
    platform.getDevices(CL_DEVICE_TYPE_ALL, &devices);

    if (devices.empty()){
        std::cerr << "No devices found!" << std::endl;
        exit(1);
    }

    /**
     * Return the first device found.
     * */

    return devices.front();
}

/**
 * Inicialize device and compile kernel code.
 * */

void initializeDevice(){

    /**
     * Select the first available device.
     * */

    device = getDefaultDevice();

    /**
     * Read OpenCL kernel file as a string.
     * */

    std::ifstream kernel_file("array_addition.cl");
    std::string src(std::istreambuf_iterator<char>(kernel_file), (std::istreambuf_iterator<char>()));

    /**
     * Compile kernel program which will run on the device.
     * */

    cl::Program::Sources sources(1, std::make_pair(src.c_str(), src.length() + 1));
    context = cl::Context(device);
    program = cl::Program(context, sources);

    auto err = program.build();
    if(err != CL_BUILD_SUCCESS){
        std::cerr << "Error!\nBuild Status: " << program.getBuildInfo<CL_PROGRAM_BUILD_STATUS>(device) 
        << "\nBuild Log:\t " << program.getBuildInfo<CL_PROGRAM_BUILD_LOG>(device) << std::endl;
        exit(1);
    }
}

/**
 * Sequentially performs the N-dimensional operation c = a + b.
 * */

void seqSumArrays(int* a, int* b, int* c, const int N){
    for(int i = 0; i < N; i++){
        c[i] = a[i] + b[i];
    }
}

/**
 * Parallelly performs the N-dimensional operation c = a + b.
 * */

void parSumArrays(int* a, int* b, int* c, const int N){

    /**
     * Create buffers and allocate memory on the device.
     * */

    cl::Buffer aBuf(context, CL_MEM_READ_ONLY | CL_MEM_HOST_NO_ACCESS | CL_MEM_COPY_HOST_PTR, N * sizeof(int), a);
    cl::Buffer bBuf(context, CL_MEM_READ_ONLY | CL_MEM_HOST_NO_ACCESS | CL_MEM_COPY_HOST_PTR, N * sizeof(int), b);
    cl::Buffer cBuf(context, CL_MEM_WRITE_ONLY | CL_MEM_HOST_READ_ONLY, N * sizeof(int));

    /**
     * Set kernel arguments.
     * */

    cl::Kernel kernel(program, "sumArrays");
    kernel.setArg(0, aBuf);
    kernel.setArg(1, bBuf);
    kernel.setArg(2, cBuf);

    /**
     * Execute the kernel function and collect its result.
     * */

    cl::CommandQueue queue(context, device);
    queue.enqueueNDRangeKernel(kernel, cl::NullRange, cl::NDRange(N));
    queue.enqueueReadBuffer(cBuf, CL_TRUE, 0, N * sizeof(int), c);
}

/**
 * Check if the N-dimensional arrays c1 and c2 are equal.
 * */

bool checkEquality(int* c1, int* c2, const int N){
    for(int i = 0; i < N; i++){
        if(c1[i] != c2[i]){
            return false;
        }
    }
    return true;
}

// Name: Diya Goyal
// Roll no: 102215255
// Question: Write a program for Splay tree having functions for the following operations:
// Insert an element (no duplicates are allowed),
// Delete an element (existing as well as non-existing),            
// Finding and deleting a minimum element,                
// Finding and deleting a maximum element,                
// Traverse the Splay tree (in-order, pre- order, and post-order),        
// Splaying (Either bottom-up approach or top-down approach), 
// Right rotation, and Left rotation.
// Acknowledgement: took help from GitHub Copilot 
#include <iostream>
#include <memory>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(NULL), right(NULL) {}
};

class SplayTree {
private:
    Node* root;

    void rotateLeft(Node*& x) {
        Node* y = x->right;
        x->right = y->left;
        y->left = x;
        x = y;
    }

    void rotateRight(Node*& x) {
        Node* y = x->left;
        x->left = y->right;
        y->right = x;
        x = y;
    }

    void splay(Node*& root, int key) {
        if (!root) return;
        Node head(0), *LeftTreeMax = &head;
        Node tail(0), *RightTreeMin = &tail;
        Node* current = root;
        while (true) {
            if (key < current->data) {
                if (!current->left) break;
                if (key < current->left->data) {
                    rotateRight(current);
                    if (!current->left) break;
                }
                RightTreeMin->left = current;
                RightTreeMin = current;
                current = current->left;
                RightTreeMin->left = NULL;
            } else if (key > current->data) {
                if (!current->right) break;
                if (key > current->right->data) {
                    rotateLeft(current);
                    if (!current->right) break;
                }
                LeftTreeMax->right = current;
                LeftTreeMax = current;
                current = current->right;
                LeftTreeMax->right = NULL;
            } else {
                break;
            }
        }
        LeftTreeMax->right = current->left;
        RightTreeMin->left = current->right;
        current->left = head.right;
        current->right = tail.left;
        root = current;
    }

    Node* insertNode(Node* root, int key) {
        if (!root) return new Node(key);
        if (key < root->data) {
            root->left = insertNode(root->left, key);
        } else if (key > root->data) {
            root->right = insertNode(root->right, key);
        }
        return root;
    }

    Node* findMin(Node* node) {
        if (!node) return NULL;
        while (node->left) node = node->left;
        return node;
    }

    Node* findMax(Node* node) {
        if (!node) return NULL;
        while (node->right) node = node->right;
        return node;
    }

    Node* removeRoot(Node* root) {
        if (!root->left) {
            Node* temp = root->right;
            delete root;
            return temp;
        }
        if (!root->right) {
            Node* temp = root->left;
            delete root;
            return temp;
        }
        Node* temp = root;
        Node* newRoot = root->left;
        splay(newRoot, findMax(root->left)->data);
        newRoot->right = temp->right;
        delete temp;
        return newRoot;
    }

    void inorderTraversal(Node* node) {
        if (!node) return;
        inorderTraversal(node->left);
        cout << node->data << " ";
        inorderTraversal(node->right);
    }

    void preorderTraversal(Node* node) {
        if (!node) return;
        cout << node->data << " ";
        preorderTraversal(node->left);
        preorderTraversal(node->right);
    }

    void postorderTraversal(Node* node) {
        if (!node) return;
        postorderTraversal(node->left);
        postorderTraversal(node->right);
        cout << node->data << " ";
    }

public:
    SplayTree() : root(NULL) {}

    void insert(int key) {
        if (!root) {
            root = new Node(key);
            return;
        }
        splay(root, key);
        if (root->data == key) return;
        root = insertNode(root, key);
        splay(root, key);
    }

    void deleteKey(int key) {
        if (!root) return;
        splay(root, key);
        if (root->data != key) return;
        root = removeRoot(root);
    }

    void deleteMin() {
        if (!root) return;
        Node* m = findMin(root);
        if (!m) return;
        int key = m->data;
        deleteKey(key);
    }

    void deleteMax() {
        if (!root) return;
        Node* m = findMax(root);
        if (!m) return;
        int key = m->data;
        deleteKey(key);
    }

    void splayKey(int key) {
        splay(root, key);
    }

    void inorder() {
        inorderTraversal(root);
        cout << endl;
    }

    void preorder() {
        preorderTraversal(root);
        cout << endl;
    }

    void postorder() {
        postorderTraversal(root);
        cout << endl;
    }
};

int main() {
    SplayTree st;
    st.insert(50);
    st.insert(30);
    st.insert(70);
    st.insert(20);
    st.insert(40);
    st.insert(60);
    st.insert(80);

    cout << "Inorder: ";   st.inorder();
    cout << "Preorder: ";  st.preorder();
    cout << "Postorder: "; st.postorder();

    st.deleteKey(30);
    cout << "\nAfter deleting 30:\nInorder: ";
    st.inorder();

    st.deleteMin();
    cout << "\nAfter deleting min:\nInorder: ";
    st.inorder();

    st.deleteMax();
    cout << "\nAfter deleting max:\nInorder: ";
    st.inorder();
    cout << endl;

    return 0;
}

